214→
215→  console.log(`\nMissing VAT: ${allMvCandidates.length} total on ${MV_ACCT}, byVatType0=${mvByVatType.length}, byNo2710=${mvByNo2710.length}`);
216→  for (const c of allMvCandidates) {
