364→  console.log(`\nCheck 4 (wrong amount on ${WA_ACCT}: ${WA_RECORDED} → ${WA_CORRECT}):`);
365→  console.log(`  ${WA_ACCT} total gross: ${acctSums[WA_ACCT] ?? 0} (corrected by -${diff})`);
366→
